export function queueSceneModel(model){
 const nodes=[['input','Traffic source','1,000 bytes / packet','client',[-7,0]],['queue','Router output queue',`${model.buffer} packet slots`,'router',[-2,0]],['output','Link output',`${model.bandwidth.toFixed(1)} Mbps`,'server',[5,0]],['drop','Tail drop','Queue full · ไม่ใช่อุปกรณ์จริง','server',[-2,5]]].map(([id,name,address,kind,position])=>({id,name,address,kind,position}));
 const links=[['input','queue'],['queue','output'],['queue','drop']].map(([from,to])=>({id:from+'-'+to,from,to,label:to==='drop'?'logical discard path':'bounded queue model'}));
 return {id:'queue',title:'Packet queue',mode:'3d',nodes,links,steps:model.steps.map(s=>({title:`tick ${s.tick} · ${model.policy}`,detail:'ตำแหน่งคิวเป็นภาพเชิงตรรกะ ไม่ใช่เส้นทาง Router หลายเครื่อง',fields:[['รอหลังส่ง',s.queue.map(p=>`${p.kind} #${p.id}`).join(', ')||'ว่าง'],['ส่งออก',s.outgoing.map(p=>`#${p.id}`).join(', ')||'ไม่มี'],['Drop',s.lost.map(p=>`#${p.id}`).join(', ')||'ไม่มี']],active:['queue',...(s.outgoing.length?['output']:[]),...(s.lost.length?['drop']:[])],edges:['input-queue',...(s.outgoing.length?['queue-output']:[]),...(s.lost.length?['queue-drop']:[])],status:s.lost.length?'blocked':'ok',nodeUpdates:{queue:`รอ ${s.queue.length}/${model.buffer} · ${model.policy}`},transfers:[...s.outgoing.map(p=>({from:'queue',to:'output',message:`${p.kind} #${p.id} · delay ${p.delay} ms`})),...s.lost.map(p=>({from:'queue',to:'drop',message:`Drop ${p.kind} #${p.id} · คิวเต็ม`}))]}))};
}
